/**
 * Corpus statique dérivé des cartes « La Terre promise » et
 * « Les environs de Jérusalem » fournies pour l'étude.
 *
 * Les positions Leaflet sont géoréférencées à partir du centre des symboles
 * visibles sur les documents fournis. Elles décrivent fidèlement la carte
 * source sans prétendre trancher une identification archéologique discutée.
 */
interface PromisedLandPlaceSeed {
  id: string;
  name: string;
  alternateNames: string[];
  mapCategory: BiblicalMapCategory;
  mapReferences: string[];
  certainty: CertaintyLevel;
  biblicalReferences: string[];
}

