const getMapLabelLevel = (id: string): MapLabelLevel => {
  if (id === 'jerusalem') return 'major';
  if (REGIONAL_LABEL_IDS.has(id)) return 'regional';
  if (STUDY_LABEL_IDS.has(id)) return 'study';
  return 'local';
};

