export const PROMISED_LAND_PLACES: BiblicalPlace[] = SEEDS.map(seed => {
  const gridReference = seed.mapReferences.join(', ');
  const mapPosition = PROMISED_LAND_MAP_POSITIONS[seed.id];
  if (!mapPosition) {
    throw new Error(`Position cartographique manquante pour ${seed.id}.`);
  }

  const sourceNote =
    mapPosition.coordinatePrecision === 'representative'
      ? 'Position représentative relevée sur la carte source pour une étendue, un relief ou un cours d’eau.'
      : 'Position géoréférencée depuis le centre du symbole de la carte source ; elle exprime la position publiée, sans transformer celle-ci en certitude archéologique.';

  return {
    id: seed.id,
    name: seed.name,
    alternateNames: seed.alternateNames,
    coordinates: mapPosition.coordinates,
    description:
      CATEGORY_DESCRIPTIONS[seed.mapCategory] ||
      'Repère identifié sur la carte source.',
    biblicalReferences: seed.biblicalReferences,
    documentaryReferences: [
      `Carte « La Terre promise », grille ${gridReference}`
    ],
    sources: [
      {
        id: 'carte-terre-promise',
        label: 'Carte « La Terre promise » et encart « Les environs de Jérusalem »',
        url: 'https://wol.jw.org/fr/wol/d/r30/lp-f/1102003103',
        citation: `« Voyez le bon pays », p. 18-19 ; référence de grille : ${gridReference}`
      }
    ],
    certainty: seed.certainty,
    notes: sourceNote,
    lastVerified: '2026-07-24',
    category: CATEGORY_LABELS[seed.mapCategory] || 'Repère cartographique',
    mapCategory: seed.mapCategory,
    mapReferences: seed.mapReferences,
    coordinatePrecision: mapPosition.coordinatePrecision,
    coordinateSource: {
      sourceId: mapPosition.sourceMapId,
      sourceMapIds: mapPosition.sourceMapIds,
      mapReference: gridReference,
      sourcePixel: mapPosition.sourcePixel,
      sourceImageSize: mapPosition.sourceImageSize,
      method: mapPosition.method
    },
    mapLabelLevel: getMapLabelLevel(seed.id)
  };
});
